INSERT INTO `tb_sensitive_words` VALUES (4343500079894626304, 1, 0, 0, 1, 1, '快速过', 4324266648077860864, '[\"4324266648077860864\"]', '', '2024-08-12 18:38:38', '2024-09-02 20:54:12', 0, '快速通关', 0, 0, '过分形容效果，以及效果和所讲的内容、方法、提供的服务产生强关联的，又被用户举报的，容易被平台判罚。特别是在挂小黄车进行售卖的时候，务必注意。');
INSERT INTO `tb_sensitive_words` VALUES (4343547078698336256, 1, 0, 3, 1, 2, '提分', 4324266648077860864, '[\"4324266648077860864\"]', '', '2024-08-12 21:45:24', '2024-09-02 19:40:35', 0, '效果承诺', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4343547322068631552, 1, 0, 3, 1, 2, '永久有效', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-12 21:46:22', '2024-09-02 19:40:54', 0, '有效期承诺', 0, 0, '过分形容服务或者售后有效期，这是平台禁止的，如果被举报、容易被平台判罚。特别是在挂小黄车进行售卖的时候，务必注意。改进方法：定一个5到10年的有效期，并不会影响转化效率。');
INSERT INTO `tb_sensitive_words` VALUES (4343547609877577728, 1, 0, 1, 1, 2, '某宝', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-12 21:47:30', '2024-09-02 19:40:57', 0, '外部平台', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4343548005983453184, 1, 0, 4, 1, 2, '节省时间', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-12 21:49:05', '2024-09-02 19:41:01', 0, '节省时间+便宜', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4343548206357938176, 1, 0, 3, 1, 2, '不要去背', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-12 21:49:53', '2024-09-02 19:41:06', 0, '不良诱导', 0, 0, '误导用户不需要付出努力，就能获得效果的，关键词多次在直播间出现或者口述，特别是被举报的，容易被平台判罚。');
INSERT INTO `tb_sensitive_words` VALUES (4343548510474338304, 1, 0, 3, 1, 2, '直接过', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-12 21:51:05', '2024-09-02 19:41:13', 0, '过度宣传', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4343548700199485440, 1, 0, 4, 1, 2, '加急发货', 1, '[\"1\"]', '', '2024-08-12 21:51:50', '2024-09-02 19:41:18', 0, '发货违规', 0, 0, '虚构发货加急服务，以引导用户做某些动作（公屏打字、关注、加团、进群等），直播间流量较大或被举报的，容易被平台判罚。');
INSERT INTO `tb_sensitive_words` VALUES (4343551505631019008, 1, 0, 3, 1, 2, '私信', 1, '[\"1\"]', '', '2024-08-12 22:02:59', '2024-09-02 19:41:23', 0, '线下引流', 0, 0, '');
INSERT INTO `tb_sensitive_words` VALUES (4345486148315906048, 1, 0, 3, 1, 1, '包退', 1, '[\"1\"]', '', '2024-08-18 06:10:34', '2024-08-18 06:13:08', 0, '售后违规', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4345495602038046720, 1, 0, 3, 1, 1, '永久', 1, '[\"1\"]', '', '2024-08-18 06:48:08', '2024-09-01 15:36:52', 0, '永久有效', 0, 0, '过分形容服务或者售后有效期，这是平台禁止的，如果被举报、容易被平台判罚。特别是在挂小黄车进行售卖的时候，务必注意。改进方法：定一个5到10年的有效期，并不会影响转化效率。');
INSERT INTO `tb_sensitive_words` VALUES (4345659244574408704, 1, 0, 3, 1, 0, '通关', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-18 17:38:23', '2024-08-19 12:38:39', 0, '通关', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4346082042912440320, 1, 0, 3, 1, 1, '一天', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-19 21:38:26', '2024-08-25 19:56:42', 0, '一天过', 0, 0, '过分形容短时间内能达成效果或功效，又被用户举报的，容易被平台判罚。特别是在挂小黄车进行售卖的时候，务必注意。例：一天拿证、三天考过、3分钟出考场');
INSERT INTO `tb_sensitive_words` VALUES (4346083480099094528, 1, 0, 3, 1, 2, '好用不', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-19 21:44:09', '2024-09-02 16:49:34', 0, '效果好', 0, 0, '在平台严查期间，直播出现任何与所提供的服务、课程、方法、产品有关联的效果和功效的正向评价词汇，又被用户举报的，容易被平台判罚。这个时候最好的方式是，只讲客观属性，不讲任何评价。');
INSERT INTO `tb_sensitive_words` VALUES (4346673551265234944, 1, 0, 3, 1, 1, '一把过', 4343491154055004160, '[\"4324266648077860864\",\"4343490887234355200\",\"4343491154055004160\"]', '', '2024-08-21 12:48:53', '2024-08-23 13:56:11', 0, '夸大效果', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4346700354302246912, 1, 0, 3, 1, 0, '抖音认证', 1, '[\"1\"]', '', '2024-08-21 14:35:23', '2024-09-02 19:41:34', 0, '借助官方宣传', 0, 0, NULL);
INSERT INTO `tb_sensitive_words` VALUES (4347053398743318528, 1, 0, 0, 1, 1, '国家', 1, '\"1\"', '', '2024-08-22 13:58:16', '2024-09-02 19:41:47', 0, '包含国家', 0, 0, NULL);
