INSERT INTO `tb_upload_file_analysis` VALUES (4355798103652040705, '5f627eb8-0195-413e-8eeb-75bc96a7f6c8', 0, '{\"videoId\":\"5f627eb8-0195-413e-8eeb-75bc96a7f6c8\",\"currentSort\":6,\"content\":\"教练说一下哈，我虽然不是做慈善的，但是九十八一百六十八我不让大家花，我今天来给大家做福利，做不到人手一个直播间呢，我只能给到大家15个名额大家呢，拼手速拼网速去抢这15个，谁能抢到算谁的？来准备好自己的手机啊，拼手速拼网速，来321上好了，怎么抢，我来教你们所有同学，屏幕下方呢，有一个蓝色小雪花，看到了没有？或者点旁边的弹窗都可以，点进去之后，那你会看到有一个100米的红包，把这个红包先领了，红包领到手之后，当你看到这个价格从129块9变成29块9的时候，去点击立即抢购，然后点击立即支付啊，某宝某信都是可以支付的，来支付成功之后的同学啊，先不要着急，别着急跑，\",\"items\":[{\"word\":\"教练\",\"startTime\":497200,\"endTime\":497655},{\"word\":\"说\",\"startTime\":497655,\"endTime\":497805},{\"word\":\"一下\",\"startTime\":497805,\"endTime\":498135},{\"word\":\"哈\",\"startTime\":498135,\"endTime\":498440},{\"word\":\"，\",\"startTime\":498135,\"endTime\":498440},{\"word\":\"我\",\"startTime\":498700,\"endTime\":499020},{\"word\":\"虽然\",\"startTime\":499020,\"endTime\":499365},{\"word\":\"不是\",\"startTime\":499365,\"endTime\":499665},{\"word\":\"做\",\"startTime\":499665,\"endTime\":499875},{\"word\":\"慈善\",\"startTime\":499875,\"endTime\":500265},{\"word\":\"的\",\"startTime\":500265,\"endTime\":500570},{\"word\":\"，\",\"startTime\":500265,\"endTime\":500570},{\"word\":\"但是\",\"startTime\":500680,\"endTime\":501120},{\"word\":\"九十八\",\"startTime\":501120,\"endTime\":501585},{\"word\":\"一百\",\"startTime\":501585,\"endTime\":501870},{\"word\":\"六十八\",\"startTime\":501870,\"endTime\":502305},{\"word\":\"我不\",\"startTime\":502305,\"endTime\":502605},{\"word\":\"让大家\",\"startTime\":502605,\"endTime\":503085},{\"word\":\"花\",\"startTime\":503085,\"endTime\":503390},{\"word\":\"，\",\"startTime\":503085,\"endTime\":503390},{\"word\":\"我\",\"startTime\":503500,\"endTime\":503790},{\"word\":\"今天\",\"startTime\":503790,\"endTime\":504135},{\"word\":\"来给\",\"startTime\":504135,\"endTime\":504420},{\"word\":\"大家\",\"startTime\":504420,\"endTime\":504660},{\"word\":\"做\",\"startTime\":504660,\"endTime\":504855},{\"word\":\"福利\",\"startTime\":504855,\"endTime\":505310},{\"wor