-- ----------------------------
-- Table structure for tb_anchor_url
-- ----------------------------
DROP TABLE IF EXISTS `tb_anchor_url`;
CREATE TABLE `tb_anchor_url`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `sec_uid` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主播唯一标识',
  `home_url` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主页url',
  `live_url` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '直播间url',
  `anchor_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主播名称',
  `anchor_avatar` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主播头像',
  `platform` tinyint NULL DEFAULT NULL COMMENT '平台类型 0：抖音 1：快手 2：视频号',
  `platform_resource` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'DouYinHomeLive(个人主页地址),DouYinLive（直播地址） 抖音直播 TiktokLive 国外版本抖音  KuaiShouLive 快手   其他待定',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '主播url' ROW_FORMAT = DYNAMIC;

