  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `trade_id` bigint NOT NULL DEFAULT 1 COMMENT '行业id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '主播表与用户表关联' ROW_FORMAT = Dynamic;

