-- ----------------------------
-- Table structure for tb_anchor_video
-- ----------------------------
DROP TABLE IF EXISTS `tb_anchor_video`;
CREATE TABLE `tb_anchor_video`  (
  `id` bigint NOT NULL,
  `video_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上传视频或录制视频时上传的id',
  `video_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '视频名称',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `paragraph` int NULL DEFAULT NULL COMMENT '第几段',
  `subsection_type` int NULL DEFAULT NULL COMMENT '分段类型 0不分段，1按时长分段，2按大小分段',
  `duration` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '时长（秒）',
  `vedio_sizie` bigint NULL DEFAULT NULL COMMENT '视频大小，单位：B',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `batch_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '归属批次号 批次号是指：在录制一个视频中，如果采用分段录制，那么这几段视频归属于同一批次 目前是采集的直播的房间Id, room_id',
  `video_type` int NULL DEFAULT NULL COMMENT '视频类型  0 ts,1 flv,2 mp4',
  `definition` int NULL DEFAULT NULL COMMENT '清晰度 0 标清 1高清 2超清 3 蓝光',
  `storage_path` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '存储路径',
  `live_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '视频url',
  `share_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `source_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '直播源地址',
  `anchor_id` int NULL DEFAULT NULL COMMENT '主播表主键',
  `is_recording` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否正在录制 0否 1是',
  `source_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '直播源类型 0 m3u8  1  flv',
  `live_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '直播标题',
  `analysis_status` int NULL DEFAULT NULL COMMENT '分析状态\r\n 0：未分析 1：分析中 2：分析完成 3分析错误',
  `analysis_time` datetime NULL DEFAULT NULL,
  `error_reason` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '错误原因',
  `sec_uid` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '主播url表的唯一标识',
  `trade_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '行业id',
  `platform_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '平台类型\r\n平台类型 0：全平台 1：抖音 2：快手 3：视频号',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `type` int NULL DEFAULT NULL COMMENT '类型 1 代表已经录制未上传分享  2 上传分享',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分享视频表' ROW_FORMAT = Dynamic;

