DROP TABLE IF EXISTS `tb_commodity`;
CREATE TABLE `tb_commodity`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名',
  `commodity_type_bean` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品类型bean的名称  vipLevel：会员等级  analysisTime：分析时长 monitorNum：监控位 anchorNum：主播数量  wordMarkTime：词语标注时长  storageNum：空间容量',
  `correlations_id` bigint NOT NULL DEFAULT 0 COMMENT '关联的id，如会员等级id',
  `is_package` tinyint NOT NULL COMMENT '是否是套餐 0：正常商品 1：套餐',
  `number` int NOT NULL COMMENT '数量',
  `status` tinyint NOT NULL COMMENT '商品状态 0：未上架 1：已上架',
  `is_give` tinyint NOT NULL DEFAULT 0 COMMENT '是否是赠送商品  0：否  1：是',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品' ROW_FORMAT = DYNAMIC;

