  `tag_id` bigint NOT NULL COMMENT '标签id，为0表示商品默认价格',
  `price` int NOT NULL COMMENT '价格，单位：分',
  `validity_num` int NOT NULL COMMENT '有效期值，跟validity_unit结合使用，如：3年',
  `validity_unit` tinyint NOT NULL COMMENT '有效期单位，0：小时 1：天 2：月 3：季度 4：年',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品价格' ROW_FORMAT = DYNAMIC;

