-- ----------------------------
-- Table structure for tb_order
-- ----------------------------
DROP TABLE IF EXISTS `tb_order`;
CREATE TABLE `tb_order`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单标题',
  `status` tinyint NOT NULL COMMENT '订单状态 0：未支付 1：生效中 2：已过期 3：已退款 4：已结束 5：超时未支付关闭',
  `quantity` int NOT NULL COMMENT '商品总数量',
  `total_price` int NOT NULL COMMENT '订单总价，单位：分',
  `is_give` tinyint NOT NULL DEFAULT 0 COMMENT '是否是赠送订单 0：否 1：是',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_order
-- ----------------------------

-- ----------------------------
-- Table structure for tb_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `tb_order_detail`;
CREATE TABLE `tb_order_detail`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `order_id` bigint NOT NULL COMMENT '订单id',
  `commindity_id` bigint NOT NULL COMMENT '商品id',
  `commodity_type_bean` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品类型bean的名称  vipLevel：会员等级  analysisTime：分析时长 monitorNum：监控位 anchorNum：主播数量',
  `commodity_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名称',
  `price` int NOT NULL COMMENT '商品单价',
  `quantity` int NOT NULL COMMENT '商品数量',
  `count_price` int NOT NULL COMMENT '商品总价，单位：分',
  `monitor_num` int NULL DEFAULT NULL COMMENT '总监控位数量',
  `ai_analysis_time` double(32, 2) NULL DEFAULT NULL COMMENT '总ai语音分析时长，单位：分钟',
  `anchor_num` int NULL DEFAULT NULL COMMENT '总添加主播数量',
  `expiration_date` datetime NOT NULL COMMENT '过期时间',
  `use_status` tinyint NOT NULL DEFAULT 0 COMMENT '使用状态 0：未生效 1：生效中 2：已过期 3：已用完',
  `is_give` tinyint NOT NULL DEFAULT 0 COMMENT '是否是赠送订单 0：否 1：是',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单-明细' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_order_detail
-- ----------------------------

-- ----------------------------
-- Table structure for tb_order_pay
-- ----------------------------
DROP TABLE IF EXISTS `tb_order_pay`;
CREATE TABLE `tb_order_pay`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `order_id` bigint NOT NULL COMMENT '订单id',
  `pay_status` tinyint NOT NULL COMMENT '支付状态 0：未支付 1：已支付 2：支付失败 3：已退款',
  `pay_type` tinyint NULL DEFAULT NULL COMMENT '支付类型 0：微信支付 1：支付宝支付',
  `pay_money` int NOT NULL COMMENT '支付金额，单位：分',
  `third_order_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '第三方支付订单号',
  `pay_date` datetime NULL DEFAULT NULL COMMENT '支付完成时间',
  `third_callback_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '第三方支付回调内容',
  `refund_order_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '系统退款号',
  `refund_third_order_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '第三方退款号',
  `refund_money` int NULL DEFAULT NULL COMMENT '退款金额',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '退款状态 0：未申请退款 1：申请退款中 2：退款成功 3：退款失败',
  `refund_error_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '退款失败原因',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单-支付信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_order_pay
-- ----------------------------

