-- ----------------------------
-- Table structure for tb_sensitive_words
-- ----------------------------
DROP TABLE IF EXISTS `tb_sensitive_words`;
CREATE TABLE `tb_sensitive_words`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `resource_type` tinyint NOT NULL COMMENT '来源类型 0：系统 1：客户自定义',
  `type` tinyint NOT NULL COMMENT '敏感词类型 0：广告 1：品牌 2：国家 3：限制词 4：其他    关键词类型 0：促单 1：互动 2：其他',
  `platform_type` tinyint NOT NULL COMMENT '平台类型 0：全平台 1：抖音 2：快手 3：视频号',
  `level` tinyint NULL DEFAULT 1 COMMENT '敏感词等级 0：1级,封号  1：2级,严重警告  2：3级警告',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '敏感词名字',
  `trade_id` bigint NOT NULL COMMENT '行业id，0表示全行业',
  `trade_id_arr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '行业id数组json',
  `similar_words` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '相似词，多个用_隔开',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `group_str` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分组',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '父id',
  `words_type` tinyint NOT NULL DEFAULT 0 COMMENT '词语类型 0：敏感词 1：关键词 2：白名单(只有客户自定义有)',
  `remarks` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '敏感词' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_sensitive_words
-- ----------------------------

