-- ----------------------------
-- Table structure for tb_upload_file
-- ----------------------------
DROP TABLE IF EXISTS `tb_upload_file`;
CREATE TABLE `tb_upload_file`  (
  `id` bigint NOT NULL,
  `file_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '文件唯一标识',
  `file_name` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `file_type` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '类型',
  `original_path` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `now_path` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小',
  `file_duration` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `error_reason` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '错误原因',
  `trade_id` bigint NULL DEFAULT NULL COMMENT '行业id',
  `platform_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `analysis_status` bigint NULL DEFAULT 0 COMMENT '分析状态  0：未分析 1：分析中 2：分析完成 3分析错误',
  `analysis_time` datetime NULL DEFAULT NULL COMMENT '分析时间',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tb_upload_file
-- ----------------------------

-- ----------------------------
-- Table structure for tb_upload_file_analysis
-- ----------------------------
DROP TABLE IF EXISTS `tb_upload_file_analysis`;
CREATE TABLE `tb_upload_file_analysis`  (
  `id` bigint NOT NULL DEFAULT 0,
  `file_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '上次upload_file的id',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态',
  `data_json` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `paragraph` int NULL DEFAULT NULL COMMENT '第几段',
  `trade_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '行业id',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0未删除 1删除  ',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '文件上传分析表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tb_upload_file_analysis
-- ----------------------------

-- ----------------------------
-- Table structure for tb_upload_file_recod
-- ----------------------------
DROP TABLE IF EXISTS `tb_upload_file_recod`;
CREATE TABLE `tb_upload_file_recod`  (
  `id` bigint NOT NULL,
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件名称',
  `file_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件id',
  `file_type` tinyint NULL DEFAULT NULL COMMENT '文件类型',
  `file_duration` bigint NULL DEFAULT NULL COMMENT '时长',
  `trade_id` int NULL DEFAULT NULL COMMENT '行业id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `sum` bigint NULL DEFAULT NULL COMMENT '总字数',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文件分析记录表' ROW_FORMAT = Dynamic;

