CREATE TABLE `tb_user_property`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `monitor_num` int NOT NULL COMMENT '拥有的监控位数量',
  `ai_analysis_time` double(32, 2) NOT NULL COMMENT '拥有的ai语音分析时长，单位：分钟',
  `anchor_num` int NOT NULL DEFAULT 0 COMMENT '能添加的主播数量',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户资产' ROW_FORMAT = DYNAMIC;

