-- Records of tb_user_property
-- ----------------------------

-- ----------------------------
-- Table structure for tb_user_property_details
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_property_details`;
CREATE TABLE `tb_user_property_details`  (
  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL COMMENT '用户id',
  `order_detail_id` bigint NOT NULL COMMENT '订单id',
  `type` tinyint NOT NULL COMMENT '类型：1 （监控位数量）monitor_num 2 （语音分析时长）ai_analysis_time  3 （添加主播数量）anchor_num',
  `num` int NOT NULL COMMENT '数量',
  `signs` tinyint NOT NULL DEFAULT 0 COMMENT '操作类型 0：减 1：加',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `monitor_num` bigint NULL DEFAULT NULL COMMENT '监控位数量',
  `ai_analysis` bigint NULL DEFAULT NULL COMMENT 'ai语音分析时长（分）',
  `anchor_num` int NULL DEFAULT NULL COMMENT '添加主播数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用户资产消费记录表' ROW_FORMAT = Dynamic;

