DROP TABLE IF EXISTS `tb_word_rule`;
CREATE TABLE `tb_word_rule`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `word_id` bigint NOT NULL COMMENT '关联的词语id',
  `type` int NOT NULL COMMENT '规则类型 0：在词语的左边范围内包含词语 1：在词语的右边范围内包含词语 2：在词语的两边任意一边范围内包含词语',
  `range_length` int NULL DEFAULT NULL COMMENT '范围长度',
  `black_or_white` tinyint NOT NULL COMMENT '0：黑名单 1：白名单 2：限定词',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '词语匹配规则' ROW_FORMAT = DYNAMIC;

